      "description": "As armas de fogo requerem munição composta por um projétil e pólvora negra. Uma rodada de munição pode variar em sua composição, mas normalmente é um cartucho de papel pré-embalado, incluindo enchimento, bala e pólvora negra, ou uma bala solta embalada manualmente. Algumas armas, como canhões de mão e bacamartes, podem disparar outros materiais, mas suas munições têm o mesmo preço devido ao custo da pólvora negra. Como fazer cartuchos de munição de arma de fogo requer a criação de pólvora negra, você precisa do talento de perícia Fabricação Alquímica para produzi-los. Munições de armas de fogo são uma opção válida para munição mágica, assim como flechas ou virotes. Criar munição mágica para armas de fogo exige que você seja capaz de criar itens alquímicos e mágicos.",
