      "name": "Caixa de pimenta",
      "description": "Esta arma é uma especialidade dos ferreiros de Alkenstar. A caixa de pimenta tem três canos, cada um segurando um único tiro, e o atirador pode girar manualmente todo o conjunto do cano para alinhar um cano carregado com o mecanismo de disparo.",
