      "name": "Guarda-chuva de dardo",
      "description": "Este guarda-chuva dispara pequenos dardos de zarabatana com um giro da alça. Os dardos são carregados na haste e, embora o dano que causam seja mínimo, o guarda-chuva de dardos é uma arma discreta, fácil de escapar nas inspeções.",
