      "name": "Manopla Broquel",
      "description": "Este escudo do tamanho de um broquel é segmentado, permitindo que ele caia em uma caixa presa a uma manopla para fácil armazenamento. Uma pequena captura permite que você expanda o escudo rapidamente na batalha quando precisar de defesa.",
